/** The text of each drawing, keyed by file name without the
    extension, for an element that draws it in a page's tokens. */
export const DIAGRAM_SOURCES: Readonly<Record<string, string>> = {
  "answer-sources": "# Source declaration = availability: every source has a precondition.\nbars\n  bands \"nothing running,files on disk,a booted installation,network reach\"\n  axis \"Required machine state\"\ntitle \"Every source has a precondition\"\ndescription \"The five sources a TYPO3 Support App tool can answer from, plotted against how much of the machine has to be running. Bundled knowledge and the server's own checkout answer with nothing running; installed packages need files on disk; the installation source needs a booted installation; network sources need outbound reach.\"\n\nrow `knowledge`\n  sub \"Bundled and version-bound.\"\n  segments 4\n  emphasis\nrow `checkout`\n  sub \"This server's own repository.\"\n  segments 4\nrow `packages`\n  sub \"Files read, never executed.\"\n  segments absent=1 3\nrow `installation`\n  sub \"Assembled runtime state.\"\n  segments absent=2 2\nrow `network`\n  sub \"Official live services.\"\n  segments absent=3 1\n\nlegend\n  ink \"available\"\n  absent \"the state this source still needs\"\n",
  "cache-key": "# One slot of the array answers two languages: the finding F1.2.\nflow claim=error columns=350,560 gap=170,16\ntitle \"One slot answers two languages\"\ndescription \"Two calls for the same key, one in German and one in English, both reach the same slot of the array. The German call writes the slot; the English call reads it and answers in German. The English path is drawn in the error colour.\"\n\nde `resolve('answer.empty', 'de')` ink at=0,0\nen `resolve('answer.empty', 'en')` ink at=0,2\ngroup \"cache[]\"\n  empty `answer.empty` value=\"Nothing found (de)\" at=1,0\n  none `answer.none` value=\"—\" at=1,1\n  tool `label.tool` value=\"Tool (de)\" at=1,2\n\nde -> empty \"writes\"\nen => empty \"answers in de\" via=h bend=0.8\n",
  "installation-fallback": "# Installation-bound answers: a fallback answers less, and says so.\nunits lines=4\n  head \"what the machine allows\"\n  key \"one square = one entry the registry could return\"\ntitle \"A fallback answers less, and says so\"\ndescription \"Each square is one entry the registry could return. The console path and the booted runtime return all of them; the package-file fallback returns every declared entry but none of the dynamically registered ones, and the answer states that.\"\n\nrow \"A console command exists\"\n  sub \"Typo3Cli::run()\"\n  note \"answeredBy: installation\"\n  parts 88\nrow \"No command — boot the runtime\"\n  sub \"Typo3Runtime::ask()\"\n  note \"answeredBy: installation\"\n  parts 88\nrow \"Failsafe mode, or unreachable\"\n  sub \"package files, read not executed\"\n  note \"answeredBy: packages\"\n  missing \"dynamic registrations, never read\"\n  parts 68 degraded=20\n",
  "lookup-cache": "# One request, two lookups of one key: the second stops at the array.\nflow\n  columns 1,1,1,1\n  gap 64,40\ntitle \"The second lookup of a key stops at the array\"\ndescription \"Two rows of the same four stops: the call, the array on the service, the catalogue reader, and the file. The first lookup passes through all four and reads the file. The second lookup hits the array and goes no further; the reader and the file stand behind dashed connectors it never follows.\"\n\nrow 0 \"First lookup\"\n  note \"an array on the service, alive for one request\"\nrow 1 \"Second lookup\"\n  note \"Both lookups answer the same label. The second answers from the array, and the file stays closed.\"\n\ncall1 `resolve()` at=0,0 ink\narray1 `cache[]` at=1,0\nreader1 `CatalogueReader` at=2,0\nfile1 `locallang.xlf` at=3,0\ncall2 `resolve()` at=0,1 ink\narray2 `cache[]` at=1,1\nreader2 `CatalogueReader` at=2,1\nfile2 `locallang.xlf` at=3,1\n\ncall1 -> array1 \"miss\"\narray1 -> reader1 \"read\"\nreader1 -> file1 \"3 ms\"\ncall2 => array2 \"hit\"\narray2 --> reader2 \"no read\"\nreader2 --> file2\n",
  "record-of-reads": "# The record, part 5: one record, three places it shows.\ncolumns\ntitle \"One record, three places it shows\"\ndescription \"The server keeps the last thirty reads of a source. The same record shows in three places: as five marks at the end of the source's row on the status page, as a list of reads on the page of the source, and as one line in the terminal. The page of the source is drawn in the accent, because that is where the record lives in full.\"\n\ncolumn\n  eyebrow \"The row on the status page\"\n  item `docs.typo3.org`\n    marks ok,ok,warn,ok,error\n    boxed\n  note \"The last five reads, oldest first. A mark is a colour and a name, so the row reads without sight.\"\n  foot \"a glance\"\ncolumn\n  eyebrow \"The page of the source\"\n  emphasis\n  item `09-15 06:00  read  3m 02s` mark=ok boxed\n  item `09-14 06:12  stopped  step 2` mark=error boxed\n  item `09-14 00:00  read  2m 58s` mark=ok boxed\n  item `09-13 18:00  slow  9m 41s` mark=warn boxed\n  foot \"the record in full, thirty reads\"\ncolumn\n  eyebrow \"The terminal\"\n  line \"$ dev-companion status docs\"\n  line \"30 reads · 27 read · 2 slow\"\n  line \"1 stopped · last 06:00 today\"\n  note \"One line, for the reader who asks from a shell and never opens a page.\"\n  foot \"a sentence\"\n",
  "slide-cache-read": "# The next call reads the same slot: the second of a row of three slides.\nflow slide=238,216 columns=1 gap=0,72\ntitle \"The next call reads it\"\ndescription \"The English call reads the same slot and answers in German. Its path is the one accent.\"\n\ncall `resolve('…', 'en')` ink at=0,0\nslot `answer.empty` value=\"found (de)\" at=0,1\n\ncall => slot \"answers in de\"\n",
  "slide-cache-slots": "# The key holds no language: the third of a row of three slides.\nflow slide=238,216 columns=1 gap=0,8\ntitle \"The key holds no language\"\ndescription \"Three slots of the array, one for each key, and none for a language.\"\n\ngroup \"cache[]\"\n  empty `answer.empty` value=\"(de)\" at=0,0\n  none `answer.none` value=\"—\" at=0,1\n  tool `label.tool` value=\"(de)\" at=0,2\n",
  "slide-cache-write": "# A call writes the slot of its key: the first of a row of three slides.\nflow slide=238,216 columns=1 gap=0,72\ntitle \"A call writes\"\ndescription \"The German call writes the slot of its key.\"\n\ncall `resolve('…', 'de')` ink at=0,0\nslot `answer.empty` value=\"found (de)\" at=0,1\n\ncall -> slot \"writes\"\n",
  "slide-lookup": "# Two calls, one slot: the lookup for a wide figure slide.\nflow slide=877,354 columns=340,370 gap=167,16\ntitle \"Two calls, one slot\"\ndescription \"A German call writes the slot of a key. An English call for the same key reads the slot and answers in German. The path of the English call is the one accent.\"\n\nde `resolve('answer.empty', 'de')` ink at=0,0\nen `resolve('answer.empty', 'en')` ink at=0,2\ngroup \"cache[]\"\n  empty `answer.empty` value=\"Nothing found (de)\" at=1,0\n  none `answer.none` value=\"—\" at=1,1\n  tool `label.tool` value=\"Tool (de)\" at=1,2\n\nde -> empty \"writes\"\nen => empty \"answers in de\" via=h bend=0.85\n",
  "slide-sources": "# The sources against the machine, in the room of a slide.\nbars\n  slide 519,401\n  bands \"nothing running,files on disk,a booted site,network reach\"\ntitle \"Five sources against the machine\"\ndescription \"Each source is a bar across what the machine has to run: bundled knowledge and the checkout need nothing, packages need files on disk, the installation a booted site, the network outbound reach. Bundled knowledge is the one accent.\"\n\nrow `knowledge`\n  sub \"bundled, versioned\"\n  segments 4\n  emphasis\nrow `checkout`\n  sub \"this repository\"\n  segments 4\nrow `packages`\n  sub \"files, never run\"\n  segments absent=1 3\nrow `installation`\n  sub \"the booted site\"\n  segments absent=2 2\nrow `network`\n  sub \"official services\"\n  segments absent=3 1\n\nlegend\n  ink \"available\"\n  absent \"what it still needs\"\n",
  "system-overview": "# Local, read-only, version-aware: one line leaves the machine.\nflow\n  columns 1,1,0.9\n  gap 120,40\ntitle \"One line leaves the machine\"\ndescription \"The MCP client asks the TYPO3 Support App subprocess, which draws its answers from bundled knowledge and from the project's own packages and installation — all inside the developer's machine. One read-only path crosses the boundary to fetch from official documentation and core services; nothing is written back across it.\"\n\ngroup machine \"your machine\"\n  client \"MCP-enabled client\"\n    at 0,0\n    span 2\n    body \"Starts one local PHP subprocess over stdio.\"\n  app \"TYPO3 Support App\"\n    at 0,1\n    span 2\n    body \"Routes by task, version and scope. Read-only, except feedback you ask for explicitly.\"\n    ink\n  knowledge `bundled knowledge`\n    at 0,2\n    body \"Curated, version-bound.\"\n  packages `packages & installation`\n    at 1,2\n    body \"What this checkout supplies.\"\ngroup outside \"outside\"\n  docs `docs.typo3.org`\n    at 2,1\n    body \"Canonical documentation.\"\n    absent\n  core `core services`\n    at 2,2\n    body \"Live registries and APIs.\"\n    absent\n\nclient <-> app \"question · answer\"\nknowledge -> app\npackages -> app\noutside => app \"read-only\"\n  via h\n",
};
